```javascript
function rotateString(str) {
  // Check if the string is not empty
  if (str.length === 0) {
    return str; // Return the original string if it's empty
  }

  // Calculate the new start index after rotation
  const startIndex = str.length - 3;

  // Use slice method to rotate the string
